/**
 * Enforces "no duplicate country for the same user": a Requested_User__c cannot have
 * two active or approved lines for the same country, whether those lines sit on the
 * same header (same submission) or on two different headers. A line whose status is
 * Rejected no longer counts, so a rejected country can be requested again.
 */
public without sharing class LSOAccessLineTriggerHandler {

    @TestVisible
    private static final Set<String> INACTIVE_LINE_STATUSES = new Set<String>{ 'Rejected' };

    public static void preventDuplicateCountries(List<LSO_CCAR_Line__c> newLines) {
        Set<Id> headerIds = new Set<Id>();
        Set<Id> countryIds = new Set<Id>();
        for (LSO_CCAR_Line__c ln : newLines) {
            if (ln.LSO_Cross_Country_Access_Request__c != null) {
                headerIds.add(ln.LSO_Cross_Country_Access_Request__c);
            }
            if (ln.Country__c != null) {
                countryIds.add(ln.Country__c);
            }
        }
        if (headerIds.isEmpty() || countryIds.isEmpty()) {
            return;
        }

        Map<Id, Id> headerToUser = new Map<Id, Id>();
        for (LSO_Cross_Country_Access_Request__c h : [
            SELECT Id, Requested_User__c
            FROM LSO_Cross_Country_Access_Request__c
            WHERE Id IN :headerIds
        ]) {
            headerToUser.put(h.Id, h.Requested_User__c);
        }

        Set<Id> relevantUserIds = new Set<Id>();
        for (Id uId : headerToUser.values()) {
            if (uId != null) {
                relevantUserIds.add(uId);
            }
        }
        if (relevantUserIds.isEmpty()) {
            return;
        }

        Map<String, Id> existingKeyToLineId = new Map<String, Id>();
        for (LSO_CCAR_Line__c existing : [
            SELECT Id, Country__c, Line_Status__c, LSO_Cross_Country_Access_Request__r.Requested_User__c
            FROM LSO_CCAR_Line__c
            WHERE Country__c IN :countryIds
            AND LSO_Cross_Country_Access_Request__r.Requested_User__c IN :relevantUserIds
            AND Line_Status__c NOT IN :INACTIVE_LINE_STATUSES
        ]) {
            String key = existing.LSO_Cross_Country_Access_Request__r.Requested_User__c + ':' + existing.Country__c;
            existingKeyToLineId.put(key, existing.Id);
        }

        Set<String> keysClaimedInThisBatch = new Set<String>();

        for (LSO_CCAR_Line__c ln : newLines) {
            if (ln.Country__c == null || ln.LSO_Cross_Country_Access_Request__c == null) {
                continue;
            }
            Id userId = headerToUser.get(ln.LSO_Cross_Country_Access_Request__c);
            if (userId == null) {
                continue;
            }
            String key = userId + ':' + ln.Country__c;

            Id existingLineId = existingKeyToLineId.get(key);
            Boolean isSelf = existingLineId != null && ln.Id != null && existingLineId == ln.Id;

            if (existingLineId != null && !isSelf) {
                ln.Country__c.addError('This user already has an active or approved request line for this country.');
            } else if (keysClaimedInThisBatch.contains(key)) {
                ln.Country__c.addError('This country is already selected more than once for the same user in this submission.');
            } else {
                keysClaimedInThisBatch.add(key);
            }
        }
    }
}
